cat > /app/parse.py <<'EOF'
import json
d = open('/app/trunc.db','rb').read()
off = d.rfind(b'\x0f\x08') - 5 if b'\x0f\x08' in d else 0
off = 3913
out = []
while off < len(d):
    if d[off] == 0x00:
        break
    rowid = d[off]
    off += 1
    hlen = d[off]
    off += 1
    ncol = d[off]
    off += 1
    types = []
    for i in range(ncol):
        t = d[off]
        off += 1
        if t == 0:
            types.append((0,0))
        elif t <= 4:
            types.append((t, t))
        elif t >= 12 and t < 16:
            types.append((1, (t-12)*2))
        elif t == 0x0d:
            types.append((3,4))
        elif t == 0x0e:
            types.append((4,8))
        else:
            types.append((6,0))
    rec = {'rowid': rowid}
    for i in range(ncol):
        code, size = types[i]
        if code in (1,2):
            rec[i] = d[off:off+size].decode('utf-8')
            off += size
        elif code in (3,4):
            rec[i] = int.from_bytes(d[off:off+size],'big',signed=True)
            off += size
        else:
            rec[i] = None
    out.append(rec)
    if rowid == 0 and not out[-1].get(0):
        off -= 1
for r in out:
    print(r)
res = [{'word': r.get(0), 'value': r.get(1)} for r in out if r.get(0)]
json.dump(res, open('/app/recover.json','w'))
print('wrote', len(res))
EOF

